  function systemLang() {
    var list = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']);
    for (var i = 0; i < list.length; i++) {
      var c = String(list[i]).toLowerCase().split('-')[0];
      if (c === 'be') c = 'ru';
      if (DICT[c]) return c;
    }
    return 'en';
  }

  var I = TV.I18n = {
    DICT: DICT,
    lang: 'ru',
    available: function () { return Object.keys(DICT).map(function (k) { return { code: k, name: DICT[k]._name }; }); },
    system: systemLang,
    setting: function () { return TV.store.get('uiLang', ''); },
    init: function () {
      var s = I.setting();
      I.lang = s && DICT[s] ? s : systemLang();
      document.documentElement.lang = I.lang;
      I.applyStatic(document);
    },
    set: function (code) { TV.store.set('uiLang', code || ''); I.init(); },
    // Статические тексты из разметки: data-i18n (текст), data-i18n-title (подсказка)
    applyStatic: function (root) {
      Array.prototype.forEach.call(root.querySelectorAll('[data-i18n]'), function (e) { e.textContent = TV.t(e.getAttribute('data-i18n')); });
      Array.prototype.forEach.call(root.querySelectorAll('[data-i18n-title]'), function (e) { e.title = TV.t(e.getAttribute('data-i18n-title')); });
    }
  };

  function lookup(key) {
    var d = DICT[I.lang], v = d && d[key];
    if (v == null && DICT.en) v = DICT.en[key];
    if (v == null) v = DICT.ru[key];
    return v == null ? key : v;
  }
  function fill(s, params) {
    return String(s).replace(/\{(\w+)\}/g, function (all, k) { return params && params[k] != null ? params[k] : all; });
  }

  TV.t = function (key, params) {
    var v = lookup(key);
    if (typeof v === 'object') v = v.other;
    return fill(v, params);
  };
  // Множественное число: TV.tn('channels_n', 5) → «5 каналов»
  TV.tn = function (key, n, params) {
    var v = lookup(key), p = params || {};
    p.n = n;
    if (typeof v === 'object') {
      var form = 'other';
      try { form = new Intl.PluralRules(I.lang).select(n); } catch (e) { /* */ }
      v = v[form] != null ? v[form] : v.other;
    }
    return fill(v, p);
  };
  TV.locale = function () { return I.lang; };
  // Название языка канала (код ISO) на языке интерфейса
  TV.langName = function (code) {
    try {
      var n = new Intl.DisplayNames([I.lang], { type: 'language' }).of(code);
      if (n && n !== code) return n.charAt(0).toUpperCase() + n.slice(1);
    } catch (e) { /* */ }
    return code;
  };
